// Demo: lwIP Integration — polling vs interrupt overhead
var pps=1*1000,intrCost=3000,pollCost=200;
var intr=pps*intrCost/1e9,poll=pollCost/1e9;
console.log('technique: lwIP Integration');console.log('packet rate: '+pps+' pps');
console.log('interrupt cost: '+intr.toFixed(2)+' cores, polling cost: '+poll.toFixed(2)+' cores');
console.log('polling wins at high packet rates');

